import extractedDetails from './assets/makita-details.json';
import {detailValues} from './part-details.js';
import makitaUrl from './assets/makita.stl?url';
import keychainUrl from './assets/keychain.stl?url';
import './style.css';
import * as THREE from 'three';
import {STLLoader} from 'three/addons/loaders/STLLoader.js';
import {OrbitControls} from 'three/addons/controls/OrbitControls.js';
import {makePart,latest,registerChange,firstSentence} from './model.js';
const I=n=>`<i class="ph ph-${n}" aria-hidden="true"></i>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=new Date().toISOString().slice(0,10),date=v=>new Date(v+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'});
const parts=[makePart({id:'7382-4916',name:'Makita blower wall mount',stem:'blower_mount',file:'makita.stl',color:0x208e83,tags:['workshop','makita'],collection:'Workshop'}),makePart({id:'1840-2301',name:'NEO keychain',stem:'neo_keychain',file:'keychain.stl',color:0x7188a4,tags:['accessories','neo'],collection:'Accessories',withCad:false})];
registerChange(parts[0],[{id:'cad',comment:'Increase clearance around the mounting screws.'},{id:'stl',comment:'Export the updated mount from CAD revision C.'},{id:'project',comment:'Reimport STL C and adjust supports.'}],{date:'2026-11-12',profile:{material:'PETG',weight:'44 g',time:'1 h 45 min'}});
registerChange(parts[0],[{id:'project',comment:'Reduce supports for a cleaner fit. Keep the same design geometry.'}],{date:'2026-11-14',profile:{material:'PETG',weight:'42 g',time:'1 h 38 min'}});
// Explicit sample assignment, not inferred CAD/3MF revision identification.
latest(parts[0]).details=structuredClone(extractedDetails);
latest(parts[0]).profile={material:'PLA',weight:'Unknown',time:'Slice required'};
registerChange(parts[1],[{id:'project',comment:'Tune the first layer for a cleaner edge.'}],{date:'2026-11-12'});
let reports=[{id:'PR-001',part:'7382-4916',version:'003',result:'Successful',printer:'Bambu Lab X1 Carbon',material:'PETG',notes:'Good fit. Keep the screw holes clear of supports.',date:'2026-11-14',photos:[]}];
let attachments=[];
let page='library',activePart=parts[0],tab='details',query='',materialFilter='',typeFilter='',collection='',viewMode='grid',selected=new Set(),saved=[],versionSelection={},expandedLog=null,focusedStl='stl',thumbs={},geometries={},disposeViewer=()=>{};
const app=document.querySelector('#app'),modal=document.querySelector('#modal');
const partById=id=>parts.find(p=>p.id===id);
const current=p=>p.versions.find(v=>v.number===versionSelection[p.id])||latest(p);
const filesOf=(v,kind)=>v.files.filter(f=>f.kind===kind);
function toast(msg){const el=document.querySelector('#toast');el.textContent=msg;el.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.style.display='none',4500)}
function button(text,action,icon,cls=''){return `<button class="${cls}" data-action="${action}">${icon?I(icon):''}${text}</button>`}
function fileBadges(v){return v.files.map(f=>`<span class="file-pill">${esc(f.kind)} <b>${esc(f.rev)}</b></span>`).join('')}
function versionOptions(p){return p.versions.toReversed().map(v=>`<option value="${v.number}" ${current(p)===v?'selected':''}>${v.number}${v===latest(p)?' · Latest':''}</option>`).join('')}
function sidebar(){return `<aside class="sidebar"><div class="brand">${I('cube-transparent')}<div>PRC<small>Printchill</small></div></div><nav class="nav" aria-label="Main navigation">${[['library','Library','squares-four',parts.length],['reports','Print Reports','clipboard-text',reports.length],['import','Import','tray-arrow-down','']].map(([id,t,i,n])=>`<button data-page="${id}" class="${page===id||page==='detail'&&id==='library'?'active':''}">${I(i)}${t}<span class="nav-count">${n}</span></button>`).join('')}</nav><div class="side-title">Collections</div>${['All parts','Workshop','Accessories'].map((c,i)=>`<button class="side-link ${page==='library'&&collection===(i?c:'')?'active':''}" data-collection="${i?c:''}">${I(i?'folder-simple':'circles-four')}${c}</button>`).join('')}<div class="side-title">Saved searches</div>${saved.length?saved.map((s,i)=>`<button class="side-link" data-saved="${i}">${I('bookmark-simple')}${esc(s.name)}</button>`).join(''):'<div class="saved-empty">Save a search to revisit your favourite parts.</div>'}<div class="sidebar-footer"><div class="avatar">M</div><div>My workshop<br><small>Local demo · v3</small></div><button class="icon ghost" data-action="settings" aria-label="Settings">${I('gear-six')}</button></div></aside>`}
function render(){disposeViewer();app.innerHTML=`<div class="layout">${sidebar()}<main class="main"><header class="topbar"><div class="row"><button class="icon ghost mobile-toggle" data-action="menu" aria-label="Open navigation">${I('list')}</button><div class="crumb">${I('folder-open')}<button data-page="library">My workshop</button><span>/</span><strong>${page==='detail'?esc(activePart.id):({library:'Library',reports:'Print Reports',import:'Import'})[page]}</strong></div></div><span class="prototype">Interactive prototype · v3</span></header><div class="content">${page==='library'?library():page==='detail'?detail():page==='reports'?reportPage():importPage()}</div></main></div>`;bind();if(page==='library')updateLibrary();if(page==='detail')initViewer(activePart)}
function library(){return `<div class="pagehead"><div><div class="eyebrow">Your designs, connected</div><h1>A home for every part.</h1><p class="sub">Find a design. Choose a version. See exactly what belongs together.</p></div>${button('Add part','import','plus','primary')}</div><div class="toolbar"><div class="search">${I('magnifying-glass')}<input id="search" aria-label="Search parts" placeholder="Search name, part number or #tag…" value="${esc(query)}"></div>${button('Filters','filters','sliders-horizontal')}${button('Save search','save-search','bookmark-simple')}<div class="view-switch"><button data-action="grid" class="${viewMode==='grid'?'active':''}" aria-label="Grid view">${I('squares-four')}</button><button data-action="list" class="${viewMode==='list'?'active':''}" aria-label="List view">${I('list-bullets')}</button></div></div><div id="filters" class="filters" ${materialFilter||typeFilter?'':'hidden'}><label>Material<select id="material"><option value="">All materials</option>${['PETG','PLA'].map(m=>`<option ${materialFilter===m?'selected':''}>${m}</option>`).join('')}</select></label><label>File type<select id="filetype"><option value="">All files</option>${['CAD','STL','3MF'].map(t=>`<option ${typeFilter===t?'selected':''}>${t}</option>`).join('')}</select></label>${button('Clear filters','clear-filters','x')}</div><div id="selection"></div><div class="meta-line"><span id="result-count"></span><span>Part name · A–Z</span></div><div id="cards"></div><div class="intro-note">${I('link')}<div><strong>One part number. A clear version history.</strong><br>Each Part version keeps its exact file revisions. Reports and attachments add context without changing the version.</div></div>`}
function filtered(){const terms=query.toLowerCase().split('+').map(t=>t.trim()).filter(Boolean);return parts.filter(p=>{const v=current(p);return(!collection||p.collection===collection)&&(!materialFilter||v.profile.material===materialFilter)&&(!typeFilter||v.files.some(f=>f.kind===typeFilter))&&terms.every(t=>t.startsWith('#')?p.tags.some(x=>x.toLowerCase()===t.slice(1)):['petg','pla'].includes(t)?v.profile.material.toLowerCase()===t:`${p.name} ${p.id}`.toLowerCase().includes(t))}).sort((a,b)=>a.name.localeCompare(b.name))}
function card(p){const v=current(p),stl=filesOf(v,'STL')[0],project=filesOf(v,'3MF')[0];return `<article class="part-card"><input type="checkbox" class="select-part" aria-label="Select ${esc(p.name)}" data-select="${p.id}" ${selected.has(p.id)?'checked':''}><button class="thumb" data-open="${p.id}" aria-label="View ${esc(p.name)} in 3D">${thumbs[p.id]?`<img src="${thumbs[p.id]}" alt="3D preview of ${esc(p.name)}">`:'<span>Loading model preview…</span>'}<span class="thumb-label">${stl?'STL · Rev '+stl.rev:'No STL'}</span></button><div class="cardbody"><div class="part-identity"><span>Part number</span><strong>${esc(p.id)}</strong></div><button class="cardtitle" data-open="${p.id}">${esc(p.name)}</button><div class="card-version"><label>Part version <select data-card-version="${p.id}" aria-label="Part version for ${esc(p.id)}">${versionOptions(p)}</select></label></div><div class="file-pills">${fileBadges(v)}</div><div class="tags">${p.tags.map(t=>`<button class="tag" data-tag="${esc(t)}">#${esc(t)}</button>`).join('')}</div><div class="card-details"><span>${esc(v.profile.material)} · ${esc(v.profile.weight)}</span><span>${I('clock')} ${esc(v.profile.time)}</span></div><p class="helper card-context">${project?`${v.details?'Sample 3MF metadata':'Demo profile'} · 3MF ${project.rev} · Part version ${v.number}`:'No print project · print data unknown'}</p><div class="card-actions">${button('Where used','where:'+p.id,'git-branch','ghost')}${button('Open project','launch:'+p.id,'arrow-square-out')}</div></div></article>`}
function updateLibrary(){const found=filtered(),cards=document.querySelector('#cards');if(!cards)return;cards.className=viewMode==='list'?'list-mode':'';cards.innerHTML=found.length?`<div class="gallery">${found.map(card).join('')}<button class="add-card" data-action="import">${I('plus-circle')}Your next idea<span>Add an STL to your workshop.</span></button></div>`:`<div class="empty"><h3>No parts found</h3>Try a different name, tag or material.<br>${button('Clear search','reset-search','arrow-counter-clockwise')}</div>`;document.querySelector('#result-count').textContent=`${found.length} ${found.length===1?'part':'parts'}`;document.querySelector('#selection').innerHTML=selected.size?`<div class="selection"><span>${selected.size} selected</span><div class="row">${button('Add tag','bulk-tag','tag')}${button('Clear','deselect','x','ghost')}</div></div>`:'';bindCards()}
function detail(){const p=activePart,v=current(p),stl=filesOf(v,'STL')[0];return `<div class="pagehead detail-heading"><div><div class="part-identity large"><span>Part number</span><strong>${esc(p.id)}</strong></div><h1>${esc(p.name)}</h1><div class="tags">${p.tags.map(t=>`<button class="tag" data-tag="${esc(t)}">#${esc(t)}</button>`).join('')}<button class="tag" data-action="single-tag">+ Add tag</button></div></div><div class="heading-actions">${button('Open file','launch:'+p.id,'arrow-square-out')}${button('Register file changes','change','git-commit','primary')}</div></div><div class="version-strip"><label>Part version <select id="part-version">${versionOptions(p)}</select></label><span>${v===latest(p)?'Latest registered version':'Historical version · fixed file revisions'}</span><span class="version-date">${date(v.date)} · ${esc(v.author)}</span></div><div class="detail-grid"><div class="viewport" id="viewer"><div class="viewer-meta"><strong>STL · Rev ${stl?.rev||'—'} · Part version ${v.number}</strong><span id="viewer-size">Loading geometry…</span></div><div class="viewer-controls">${[['reset-view','Reset view','arrows-clockwise'],['bounds','Show dimensions','bounding-box'],['zoom-in','Zoom in','magnifying-glass-plus'],['zoom-out','Zoom out','magnifying-glass-minus']].map(([a,l,i])=>`<button data-action="${a}" aria-label="${l}">${I(i)}</button>`).join('')}</div><div class="dimensions" id="dimensions" hidden></div></div><section class="baseline"><div class="baseline-top"><h2>Files in version ${v.number}</h2>${I('files')}</div><p class="sub">Exact revisions. One clear design context.</p><div class="chain">${chain(v)}</div><div class="baseline-foot">${v===latest(p)?'Register a file change to create the next Part version.':'This version stays unchanged when newer files are registered.'}<br>Reports and attachments do not increase this number.</div></section></div><div class="tabs" role="tablist">${[['details','Part Details'],['where','Where used'],['logbook','Logbook'],['reports','Print Reports'],['attachments','Attachments']].map(([id,t])=>`<button role="tab" aria-selected="${tab===id}" data-tab="${id}" class="${tab===id?'active':''}">${t}${id==='attachments'?` <span class="badge-count">${attachments.filter(a=>a.part===p.id&&a.version===v.number).length}</span>`:''}</button>`).join('')}</div><section id="tab-content">${tabContent()}</section>`}
function chain(v){return v.files.map(f=>`<button class="chain-row" data-file="${f.id}" aria-label="${f.kind==='STL'?'Explore relationships for':'View revision of'} ${esc(f.name)}"><span class="file-icon">${f.kind}</span><strong>${esc(f.name)}</strong><span class="version">${f.rev}</span></button>`).join('')}
function partDetails(v){
 const project=filesOf(v,'3MF')[0],d=v.details,values=detailValues(d);
 const metric=(name,value,context)=>`<div class="detail-metric"><dt>${name}</dt><dd>${esc(value)}</dd><small>${context}</small></div>`;
 return `<div class="panel-heading"><div><h2>Print setup</h2><p class="sub">Part version ${v.number}${project?' · 3MF revision '+project.rev:' · No 3MF file'}</p></div><span class="details-scope">${d?'3MF project settings':'Metadata unavailable'}</span></div>
 <dl class="detail-metrics">${metric('Material',values.material,'Selected project filament materials')}${metric('Total weight',values.weight,'Saved slicing estimate · all plates')}${metric('Print time · indication',values.time,d?.printTimeSeconds!=null?'Slicer estimate · rounded to 5 min · all plates':'Slice all plates to obtain an indication')}${metric('Layer height',values.height,'Project setting')}${metric('Infill',values.density,'Project setting')}${metric('Infill type',values.pattern,'Project setting')}${metric('Plates in 3MF',values.plates,'Full project')}</dl>
 <section class="filament-panel"><div class="panel-heading"><div><h3>Selected filament colours & types</h3><p class="sub">${values.filaments.length?`${d?.selectionBasis==='saved_slicing_usage'?'Saved slicing usage':'Model assignments'} · ${values.filaments.length} selected of ${d?.filaments?.length||0} configured project filaments. Not a live AMS inventory.`:'No filament metadata available for this revision.'}</p></div></div>${values.filaments.length?`<div class="filament-grid">${values.filaments.map(f=>{const color=/^#[0-9a-f]{6}(?:[0-9a-f]{2})?$/i.test(f.color||'')?f.color:null;return `<div class="filament-card"><div class="filament-color" ${color?`style="background-color:${color}"`:''} aria-label="${esc(color||'Unknown colour')}"></div><div><small>Filament ${f.slot}</small><strong>${esc(f.type||'Unknown type')}</strong><span class="filament-profile">${esc(f.profile||'Profile unknown')}</span><span>${esc(f.color||'Unknown colour')}</span><em>${f.usageConfirmed?'Included in slicing estimate':'Selected on model'}</em></div></div>`}).join('')}</div>`:''}${d&&!d.selectionComplete?'<p class="helper">Selection is incomplete. Painted colours, support and other assignments may require slicing to resolve.</p>':''}</section>
 ${d&&d.printTimeSeconds==null?button('How to obtain a time indication','time-help','clock','ghost'):''}
 <div class="details-note">${I('info')}<div>${d?`Source: <strong>${esc(d.sourceFile)}</strong><br>Project settings apply to the full 3MF, which can contain other parts. Object/plate overrides and variable layer heights are not resolved here.${d.overridesPresent?.length?' Overrides detected in the file.':''}<br>${esc(d.statisticsNote)}<br><span class="helper">Extracted from the supplied sample and assigned to demo revision G; automatic revision matching is not connected.</span>`:'No 3MF metadata has been registered for this revision. Missing values remain Unknown; data from another version is never substituted.'}</div></div>`;
}
function sourceLabel(file){if(file.source)return `Exported from CAD ${file.source.rev}`;if(file.sources)return `Uses ${file.sources.map(s=>'STL '+s.rev).join(', ')}`;return file.kind==='STL'?'CAD source unknown':'Native CAD document'}
function tabContent(){const p=activePart,v=current(p);if(tab==='details')return partDetails(v);if(tab==='where')return whereContent(p);if(tab==='logbook')return logbook(p);if(tab==='attachments')return attachmentContent(p,v);return `<div class="panel-heading"><div><h2>Print attempts</h2><p class="sub">Part version ${v.number} · Adding a report does not create a new version.</p></div>${button('Add Print Report','report','plus','primary')}</div>${reportRows(reports.filter(r=>r.part===p.id&&r.version===v.number))}`}
function whereContent(p){const v=current(p),stls=filesOf(v,'STL'),stl=stls.find(f=>f.id===focusedStl)||stls[0];if(!stl)return '<div class="empty">No STL in this Part version.</div>';focusedStl=stl.id;const parents=new Map();for(const pv of p.versions)for(const file of pv.files)if(file.sources?.some(s=>s.id===stl.id&&s.rev===stl.rev))parents.set(file.id+':'+file.rev,file);const uses=[...parents.values()],width=Math.max(840,uses.length*240),center=width/2,positions=uses.map((_,i)=>width*(i+.5)/uses.length);const node=(file,x,y,role)=>`<foreignObject x="${x-100}" y="${y}" width="200" height="95"><div xmlns="http://www.w3.org/1999/xhtml" class="graph-node ${role==='selected'?'selected':''}"><button data-graph-file="${esc(file.id)}:${esc(file.rev)}"><span class="node-kind">${file.kind} · Rev ${file.rev}</span><strong>${esc(file.name)}</strong><small>${role==='selected'?'Selected STL':role==='source'?'CAD source':'Uses selected STL'}</small></button></div></foreignObject>`;const source=stl.source?p.versions.flatMap(v=>v.files).find(f=>f.id===stl.source.id&&f.rev===stl.source.rev):null;return `<div class="panel-heading"><div><h2>Where used</h2><p class="sub">STL ${stl.rev} from Part version ${v.number} · All known exact-revision relationships</p></div>${stls.length>1?`<select id="graph-stl" aria-label="Selected STL">${stls.map(f=>`<option value="${f.id}" ${f.id===stl.id?'selected':''}>${esc(f.name)} · ${f.rev}</option>`).join('')}</select>`:''}</div><div class="relation-scroll"><svg class="relation-diagram" viewBox="0 0 ${width} 460" style="min-width:${width}px" role="group" aria-label="Relationship diagram: 3MF users above the STL, CAD source below"><text x="24" y="24" class="graph-label">USED IN · ${uses.length} PROJECT REVISIONS</text>${positions.map(x=>`<path d="M ${center} 220 V 175 H ${x} V 125" class="graph-line"/>`).join('')}${source?`<path d="M ${center} 305 V 350" class="graph-line"/>`:''}${uses.map((f,i)=>node(f,positions[i],40,'parent')).join('')}${uses.length?'':`<text x="${center}" y="94" text-anchor="middle" class="graph-label">No known users for this STL revision</text>`}${node(stl,center,220,'selected')}${source?node(source,center,350,'source'):`<text x="${center}" y="385" text-anchor="middle" class="graph-label">CAD source unknown · no relationship assumed</text>`}</svg></div><p class="helper">Relationships use document identity + exact revision, not matching revision letters. Demo relationships are explicit sample data; no file analysis is running.</p>`}
function logbook(p){const v=current(p);return `<div class="panel-heading"><div><h2>Part history</h2><p class="sub">Part number ${esc(p.id)} · ${p.versions.length} registered versions · File changes only</p></div>${button('Register file changes','change','git-commit')}</div><div class="commit-graph">${p.versions.toReversed().map(item=>{const open=expandedLog===item.number;return `<article class="commit-entry ${item.number===v.number?'current':''}"><button class="commit-dot" data-log="${item.number}" aria-label="${open?'Collapse':'Expand'} Part version ${item.number}" aria-expanded="${open}" aria-controls="log-${item.number}"></button><div class="commit-body"><button class="commit-summary" data-log="${item.number}" aria-expanded="${open}"><span class="part-version-badge">${item.number}</span><strong>${esc(firstSentence(item))}</strong>${I(open?'caret-up':'caret-down')}</button><div class="commit-meta">${date(item.date)} · ${esc(item.author)} · ${item.changes.length} ${item.changes.length===1?'file':'files'} ${item.number==='001'?'registered':'changed'}${item===latest(p)?' · Latest':''}</div><div class="commit-balloon" id="log-${item.number}" ${open?'':'hidden'}><div class="panel-heading"><h3>Files in Part version ${item.number}</h3><button data-select-history="${item.number}">View this version ${I('arrow-up-right')}</button></div>${item.files.map(f=>{const change=item.changes.find(c=>c.id===f.id);return `<div class="log-file"><span class="file-icon">${f.kind}</span><div><strong>${esc(f.name)} · Rev ${f.rev}</strong><p>${change?esc(change.comment||'Revision updated; no comment provided.'):'Unchanged from previous Part version.'}</p></div><span class="log-status">${change?(item.number==='001'?'Added':'Changed'):'Unchanged'}</span></div>`}).join('')}</div></div></article>`}).join('')}</div>`}
function attachmentContent(p,v){const items=attachments.filter(a=>a.part===p.id&&a.version===v.number);return `<div class="panel-heading"><div><h2>Supporting files & software</h2><p class="sub">Part version ${v.number} · Adding attachments does not change the Part version.</p></div><div class="row">${button('Link Git version','git-link','git-branch')}${button('Upload file','attach','paperclip','primary')}</div></div>${items.length?`<div class="attachment-list">${items.map(a=>`<article class="attachment-row">${I(a.kind==='git'?'git-branch':'file-text')}<div><h3>${esc(a.name)}</h3>${a.kind==='git'?`<p class="sub">${esc(a.url)}</p><p class="helper">${a.exact?'Commit':'Mutable ref'}: ${esc(a.ref)}</p>`:`<p class="sub">${(a.size/1024).toFixed(1)} KB · ${date(a.date)}</p>`}</div><span class="version">${v.number}</span><a class="download-link" href="${esc(a.kind==='git'?a.target:a.url)}" ${a.kind==='git'?'target="_blank" rel="noopener noreferrer"':`download="${esc(a.name)}"`}>${a.kind==='git'?'Open repository':'Download'} ${I('arrow-square-out')}</a></article>`).join('')}</div>`:`<div class="empty">${I('paperclip')}<h3>Everything that helps build this version.</h3>Add an assembly guide, wiring diagram or a link to a software commit.</div>`}<p class="helper">Attachments are specific to this version and are not automatically copied to newer versions. Browser-memory storage only.</p>`}
function reportRows(items){return items.length?items.map(r=>`<article class="snap-row">${I('clipboard-text')}<div class="snap-copy"><h3>${r.id} · ${esc(partById(r.part).name)}</h3><p class="sub">Part number ${r.part} · Part version ${r.version}</p><div class="report-meta">${esc(r.printer)} · ${esc(r.material)} · ${date(r.date)}</div></div><span class="result ${r.result!=='Successful'?'failed':''}">${r.result}</span><button data-report-open="${r.id}">Read report ${I('arrow-up-right')}</button></article>`).join(''):'<div class="empty">No print attempts recorded for this Part version.</div>'}
function reportPage(){return `<div class="pagehead"><div><div class="eyebrow">Learn from every print</div><h1>Print Reports</h1><p class="sub">Every attempt stays linked to the exact Part version that was printed.</p></div>${button('Add report','report','plus','primary')}</div>${reportRows(reports)}`}
function importPage(){return `<div class="pagehead"><div><div class="eyebrow">Bring your designs together</div><h1>Add a part</h1><p class="sub">Start with an STL as Part version 001. Missing CAD sources stay unknown.</p></div></div><div class="dropzone" id="dropzone">${I('cloud-arrow-up')}<h2>Drop an STL here</h2><p class="sub">Or choose a local file. Maximum 25 MB in this demo.</p><input id="stl-upload" type="file" accept=".stl" aria-label="Choose STL file"></div><div class="upload-note">${I('info')} Data stays in this browser tab and disappears on refresh. No CAD extraction or slicer connector is connected.</div><div class="panel-heading"><h2>Inspect a SolidWorks metadata export</h2></div><p class="sub">Read custom properties from the POC macro JSON.</p><input id="json-upload" type="file" accept=".json" aria-label="Choose metadata JSON"><div id="json-result"></div>`}
function openModal(title,body,footer=''){modal.onpaste=null;modal.innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="icon ghost" id="close-modal" aria-label="Close">${I('x')}</button></div><div class="modal-body">${body}<div id="form-error" class="error" role="alert"></div></div>${footer?`<div class="modal-foot">${footer}</div>`:''}`;document.querySelector('#close-modal').onclick=()=>modal.close();modal.showModal()}
function formError(text){document.querySelector('#form-error').textContent=text}
function changeModal(){const p=activePart,base=latest(p),number=String(Number(base.number)+1).padStart(3,'0');openModal('Register file changes',`<p class="sub">Part number <b>${p.id}</b> · Based on latest version <b>${base.number}</b>. All selected changes create one new Part version <b>${number}</b>.</p><div class="warnbox">Prototype: this simulates file revisions. It does not edit or detect changes in real CAD/STL/3MF files.</div>${base.files.map(f=>`<div class="change-file"><label><input type="checkbox" data-change-file="${f.id}"> ${esc(f.name)} · ${f.rev} → ${f.rev==='Z'?'undefined':String.fromCharCode(f.rev.charCodeAt(0)+1)}</label><textarea data-file-comment="${f.id}" aria-label="Comment for ${esc(f.name)}" placeholder="What changed in this file? (optional)"></textarea></div>`).join('')}<p class="helper">Dependent files are not revised automatically. If the STL is re-exported or the 3MF reimported, include that file too.</p><label for="change-material">Material · updated 3MF demo profile</label><select id="change-material"><option ${base.profile.material==='PETG'?'selected':''}>PETG</option><option ${base.profile.material==='PLA'?'selected':''}>PLA</option></select><p class="helper">Material only changes when the 3MF is selected. Print Reports and attachments do not create versions.</p>`,button('Cancel','cancel')+button('Create Part version '+number,'confirm-change','git-commit','primary'));document.querySelector('[data-action="cancel"]').onclick=()=>modal.close();document.querySelector('[data-action="confirm-change"]').onclick=()=>{const changes=[...document.querySelectorAll('[data-change-file]:checked')].map(el=>({id:el.dataset.changeFile,comment:document.querySelector(`[data-file-comment="${el.dataset.changeFile}"]`).value}));try{const profile=structuredClone(base.profile);if(changes.some(c=>base.files.find(f=>f.id===c.id).kind==='3MF'))profile.material=document.querySelector('#change-material').value;const v=registerChange(p,changes,{date:today,profile});versionSelection[p.id]=v.number;expandedLog=v.number;modal.close();tab='logbook';render();toast('Part version '+v.number+' created. Earlier versions are unchanged.')}catch(e){formError(e.message)}}}
function tagModal(bulk){const ids=bulk?[...selected]:[activePart.id];openModal('Add tags',`<p class="sub">Add a tag to ${ids.length} selected ${ids.length===1?'part':'parts'}.</p><label for="tag-input">Tag</label><input id="tag-input" placeholder="#workshop"><p class="helper">No spaces. Tags are case-insensitive.</p>`,button('Add tag','save-tag','tag','primary'));document.querySelector('[data-action="save-tag"]').onclick=()=>{const value=document.querySelector('#tag-input').value.replace(/^#/,'').trim();if(!/^[-_\p{L}\p{N}]+$/u.test(value))return formError('Use letters, numbers, - or _. No spaces or extra #.');const existing=parts.flatMap(p=>p.tags).find(t=>t.toLowerCase()===value.toLowerCase())||value;ids.forEach(id=>{const p=partById(id);if(!p.tags.some(t=>t.toLowerCase()===existing.toLowerCase()))p.tags.push(existing)});modal.close();render();toast('Tag added.')};}
function reportModal(){const choices=page==='reports'?parts.flatMap(p=>p.versions.map(v=>({p,v}))):[{p:activePart,v:current(activePart)}];let photos=[];openModal('Record a print attempt',`<p class="sub">This adds a report without changing the Part version.</p><label for="report-version">Printed Part version</label><select id="report-version">${choices.map(({p,v})=>`<option value="${p.id}:${v.number}">${p.id} · ${esc(p.name)} · Version ${v.number}</option>`).join('')}</select><div class="form-grid"><div><label for="printer">Printer</label><input id="printer" value="Bambu Lab X1 Carbon"></div><div><label for="report-material">Material</label><input id="report-material" value="${esc(choices[0].v.profile.material)}"></div></div><label for="outcome">Result</label><select id="outcome"><option>Successful</option><option>Failed</option><option>Aborted</option></select><label for="notes">Observations & measurements</label><textarea id="notes"></textarea><label for="photo-upload">Photos / screenshots</label><input id="photo-upload" type="file" accept="image/png,image/jpeg,image/webp" multiple><div class="photos" id="photo-preview"></div><p class="helper">Paste screenshots with Ctrl+V. Up to 5 images, 5 MB each.</p>`,button('Save Print Report','save-report','check','primary'));const addPhotos=async files=>{for(const file of files){if(photos.length>=5){formError('Maximum 5 images.');break}if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>5*1024*1024){formError('Choose PNG, JPEG or WebP up to 5 MB.');continue}photos.push(await dataUrl(file));}if(document.querySelector('#photo-preview'))document.querySelector('#photo-preview').innerHTML=photos.map(src=>`<img src="${src}" alt="Print attempt photo">`).join('')};document.querySelector('#photo-upload').onchange=e=>addPhotos(e.target.files);modal.onpaste=e=>{const files=[...e.clipboardData.items].filter(x=>x.kind==='file').map(x=>x.getAsFile());if(files.length){e.preventDefault();addPhotos(files)}};document.querySelector('#report-version').onchange=e=>{const [id,number]=e.target.value.split(':');document.querySelector('#report-material').value=partById(id).versions.find(v=>v.number===number).profile.material};document.querySelector('[data-action="save-report"]').onclick=()=>{const [part,version]=document.querySelector('#report-version').value.split(':'),printer=document.querySelector('#printer').value.trim();if(!printer)return formError('Enter a printer, or enter Unknown.');reports.unshift({id:`PR-${String(reports.length+1).padStart(3,'0')}`,part,version,printer,material:document.querySelector('#report-material').value,result:document.querySelector('#outcome').value,notes:document.querySelector('#notes').value,date:today,photos});modal.close();render();toast('Print Report saved. Part version unchanged.')};}
function showReport(id){const r=reports.find(r=>r.id===id);openModal(r.id+' · Print Report',`<p class="sub">Part number <b>${r.part}</b> · Part version <b>${r.version}</b></p><span class="result ${r.result!=='Successful'?'failed':''}">${r.result}</span><div class="facts"><div><dt>Printer</dt><dd>${esc(r.printer)}</dd></div><div><dt>Material</dt><dd>${esc(r.material)}</dd></div></div><h3>Observations & measurements</h3><p class="sub" style="white-space:pre-wrap">${esc(r.notes)||'No observations recorded.'}</p><div class="photos">${r.photos.map(src=>`<img src="${src}" alt="Print attempt photo">`).join('')}</div>`)}
function attachModal(){const p=activePart,v=current(p);openModal('Upload an attachment',`<p class="sub">Part number <b>${p.id}</b> · Part version <b>${v.number}</b>. This will not create a new Part version.</p><label for="attachment-file">Assembly guide, wiring diagram or supporting file</label><input id="attachment-file" type="file"><p class="helper">Up to 10 MB. Stored only in this browser tab; never executed by this application.</p>`,button('Add attachment','save-attachment','paperclip','primary'));document.querySelector('[data-action="save-attachment"]').onclick=()=>{const f=document.querySelector('#attachment-file').files[0];if(!f)return formError('Choose a file.');if(f.size>10*1024*1024)return formError('Maximum attachment size is 10 MB.');attachments.push({id:crypto.randomUUID(),part:p.id,version:v.number,kind:'file',name:f.name,size:f.size,date:today,url:URL.createObjectURL(f)});modal.close();render();toast('Attachment added to version '+v.number+'. Part version unchanged.')};}
function gitModal(){const p=activePart,v=current(p);openModal('Link a software version',`<p class="sub">Link software to Part version <b>${v.number}</b> without changing the design version.</p><label for="git-name">Label</label><input id="git-name" placeholder="Controller firmware"><label for="git-url">Git repository URL</label><input id="git-url" type="url" placeholder="https://github.com/owner/repository"><label for="git-ref">Commit SHA or ref</label><input id="git-ref" placeholder="Full commit SHA recommended"><p class="helper">A full 40- or 64-character commit SHA identifies a fixed software revision. Branches and tags are labelled mutable. This demo does not verify the repository or commit.</p>`,button('Add Git link','save-git','git-branch','primary'));document.querySelector('[data-action="save-git"]').onclick=()=>{try{const url=new URL(document.querySelector('#git-url').value.trim()),ref=document.querySelector('#git-ref').value.trim();if(!['https:','http:'].includes(url.protocol)||url.username||url.password)throw Error('Use an HTTP(S) repository URL without credentials.');if(!ref)throw Error('Enter a commit SHA or ref.');const exact=/^(?:[0-9a-f]{40}|[0-9a-f]{64})$/i.test(ref);attachments.push({id:crypto.randomUUID(),kind:'git',part:p.id,version:v.number,name:document.querySelector('#git-name').value.trim()||'Software repository',url:url.href,target:url.href,ref,exact,date:today});modal.close();render();toast('Git version linked. Part version unchanged.')}catch(e){formError(e.message)}}}
function launch(id){const p=partById(id),v=current(p);openModal('Open a design file',`<p class="sub">Part number <b>${p.id}</b> · Part version <b>${v.number}</b></p><div class="chain">${chain(v)}</div><div class="warnbox">Prototype only. No desktop connector is installed; SolidWorks and your slicer will not launch.</div>`)}
function fileInfo(file){openModal('Document revision',`<h3>${esc(file.name)}</h3><p class="sub">${file.kind} · Revision ${file.rev}</p><p class="helper">${esc(sourceLabel(file))}</p><div class="warnbox">Demo record. Real file opening and revision-specific geometry are not connected.</div>`)}
function bind(){document.querySelectorAll('[data-page]').forEach(el=>el.onclick=()=>{page=el.dataset.page;collection='';render()});document.querySelectorAll('[data-collection]').forEach(el=>el.onclick=()=>{collection=el.dataset.collection;page='library';render()});document.querySelectorAll('[data-saved]').forEach(el=>el.onclick=()=>{const s=saved[Number(el.dataset.saved)];query=s.query;materialFilter=s.material;typeFilter=s.type;page='library';render()});if(page==='library'){document.querySelector('#search').oninput=e=>{query=e.target.value;updateLibrary()};document.querySelector('#material').onchange=e=>{materialFilter=e.target.value;updateLibrary()};document.querySelector('#filetype').onchange=e=>{typeFilter=e.target.value;updateLibrary()}}if(page==='import'){document.querySelector('#stl-upload').onchange=e=>importStl(e.target.files[0]);const z=document.querySelector('#dropzone');z.ondragover=e=>e.preventDefault();z.ondrop=e=>{e.preventDefault();importStl(e.dataTransfer.files[0])};document.querySelector('#json-upload').onchange=e=>importJson(e.target.files[0])}bindCards();if(page==='detail')document.querySelector('#part-version').onchange=e=>{versionSelection[activePart.id]=e.target.value;render()};bindDetail();}
function bindCards(){document.querySelectorAll('[data-open]').forEach(el=>el.onclick=()=>{activePart=partById(el.dataset.open);page='detail';tab='details';render()});document.querySelectorAll('[data-select]').forEach(el=>el.onchange=()=>{el.checked?selected.add(el.dataset.select):selected.delete(el.dataset.select);updateLibrary()});document.querySelectorAll('[data-card-version]').forEach(el=>el.onchange=()=>{versionSelection[el.dataset.cardVersion]=el.value;updateLibrary()});document.querySelectorAll('[data-tag]').forEach(el=>el.onclick=()=>{query='#'+el.dataset.tag;page='library';render()});bindActions()}
function refreshTab(){document.querySelector('#tab-content').innerHTML=tabContent();bindDetail()}
function bindDetail(){document.querySelectorAll('[data-tab]').forEach(el=>el.onclick=()=>{tab=el.dataset.tab;document.querySelectorAll('[data-tab]').forEach(b=>{b.classList.toggle('active',b===el);b.setAttribute('aria-selected',String(b===el))});refreshTab()});document.querySelectorAll('[data-file]').forEach(el=>el.onclick=()=>{const f=current(activePart).files.find(f=>f.id===el.dataset.file);if(f.kind==='STL'){focusedStl=f.id;tab='where';render()}else fileInfo(f)});document.querySelectorAll('[data-log]').forEach(el=>el.onclick=()=>{expandedLog=expandedLog===el.dataset.log?null:el.dataset.log;refreshTab();document.querySelector(`.commit-dot[data-log="${el.dataset.log}"]`)?.focus()});document.querySelectorAll('[data-select-history]').forEach(el=>el.onclick=()=>{versionSelection[activePart.id]=el.dataset.selectHistory;render()});document.querySelectorAll('[data-graph-file]').forEach(el=>el.onclick=()=>{const [id,rev]=el.dataset.graphFile.split(':');const f=activePart.versions.flatMap(v=>v.files).find(f=>f.id===id&&f.rev===rev);if(f)fileInfo(f)});const graphSelect=document.querySelector('#graph-stl');if(graphSelect)graphSelect.onchange=e=>{focusedStl=e.target.value;refreshTab()};bindActions()}
function bindActions(){document.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>action(el.dataset.action));document.querySelectorAll('[data-report-open]').forEach(el=>el.onclick=()=>showReport(el.dataset.reportOpen))}
function action(a){if(a.startsWith('launch:'))return launch(a.slice(7));if(a.startsWith('where:')){activePart=partById(a.slice(6));page='detail';tab='where';return render()}switch(a){case'menu':return document.querySelector('.sidebar').classList.toggle('open');case'import':page='import';return render();case'filters':{const f=document.querySelector('#filters');f.hidden=!f.hidden;return}case'clear-filters':materialFilter='';typeFilter='';return render();case'reset-search':query='';materialFilter='';typeFilter='';return render();case'grid':case'list':viewMode=a;return render();case'deselect':selected.clear();return updateLibrary();case'bulk-tag':return tagModal(true);case'single-tag':return tagModal(false);case'change':return changeModal();case'report':return reportModal();case'attach':return attachModal();case'git-link':return gitModal();case'save-search':return saveSearch();case'reset-view':case'bounds':case'zoom-in':case'zoom-out':return viewerAction(a);case'time-help':return openModal('Print time indication','<p class="sub">Slice all plates in Bambu Studio with the intended printer and settings. Save or export a 3MF that includes the slicing results. Printchill can read the saved per-plate estimate and present an indication rounded to five minutes.</p><p class="helper">This prototype reads prepared sample metadata; it does not run a slicer or import a new sliced 3MF through the browser yet. Filament length and nozzle speed alone are insufficient for a useful estimate.</p>');case'settings':return openModal('About this prototype','<p class="sub">Data stays in browser memory. Refresh resets the demo. No server storage, CAD/slicer connector or printer connection. Snapshots are reserved for a later baselining workflow.</p>')}}
function saveSearch(){openModal('Save search',`<label for="query-name">Search name</label><input id="query-name"><p class="helper">${esc(query||'All parts')} · ${esc(materialFilter||'All materials')} · ${esc(typeFilter||'All file types')}</p>`,button('Save search','confirm-search','bookmark-simple','primary'));document.querySelector('[data-action="confirm-search"]').onclick=()=>{const name=document.querySelector('#query-name').value.trim();if(!name)return formError('Enter a name.');saved.push({name,query,material:materialFilter,type:typeFilter});modal.close();render()}}
function dataUrl(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)})}
async function importStl(file){if(!file)return;if(!/\.stl$/i.test(file.name)||file.size>25*1024*1024)return toast('Choose an STL up to 25 MB.');try{const geo=new STLLoader().parse(await file.arrayBuffer()),position=geo.getAttribute('position');if(!position?.count||!position.array.every(Number.isFinite))throw Error('Invalid geometry');geo.computeBoundingBox();if(!Number.isFinite(geo.boundingBox.max.length())||geo.boundingBox.isEmpty())throw Error('Empty geometry');const id='LOCAL-'+String(parts.length+1).padStart(3,'0'),name=file.name.replace(/\.stl$/i,''),p=makePart({id,name,stem:name,file:null,color:0x208e83,withCad:false});p.versions[0].files=p.versions[0].files.filter(f=>f.kind==='STL');p.versions[0].changes=[{id:'stl',comment:'STL imported. CAD source unknown.'}];p.versions[0].profile={material:'Unknown',time:'—',weight:'—'};p.versions[0].date=today;geometries[id]=prepareGeometry(geo);parts.push(p);thumbs[id]=makeThumbnail(p);activePart=p;page='detail';tab='details';render();toast('STL imported as Part version 001.')}catch(e){toast('Unable to read STL: '+e.message)}}
async function importJson(file){if(!file)return;if(file.size>5*1024*1024)return toast('Maximum JSON size is 5 MB.');try{const data=JSON.parse(await file.text());if(!Array.isArray(data.document_properties))throw Error('Missing document_properties array');document.querySelector('#json-result').innerHTML=`<h3>${esc(data.source?.file_name||file.name)}</h3><p class="helper">Read only. No automatic revision or source linking.</p><table><thead><tr><th>Property</th><th>Value</th><th>Read status</th></tr></thead><tbody>${data.document_properties.map(p=>`<tr><td>${esc(p.name)}</td><td>${esc(p.resolved_value??p.raw_value??'Unknown')}</td><td>${esc(p.read_status||'Unknown')}</td></tr>`).join('')}</tbody></table>`}catch(e){toast('Unable to read JSON: '+e.message)}}
// Actual supplied STL geometry, shared by thumbnails and interactive viewer.
function prepareGeometry(g){g.computeVertexNormals();g.computeBoundingBox();const size=new THREE.Vector3();g.boundingBox.getSize(size);g.userData.dimensions=size.toArray();g.center();g.rotateX(-Math.PI/2);return g}
function sceneFor(p,w,h){const renderer=new THREE.WebGLRenderer({antialias:true,alpha:false,preserveDrawingBuffer:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.setSize(w,h);renderer.setClearColor(0xedf2f3);renderer.outputColorSpace=THREE.SRGBColorSpace;const scene=new THREE.Scene(),camera=new THREE.PerspectiveCamera(34,w/h,.01,100000),geometry=geometries[p.id],mesh=new THREE.Mesh(geometry,new THREE.MeshStandardMaterial({color:p.color,roughness:.6,metalness:.08}));scene.add(mesh);const size=new THREE.Vector3();new THREE.Box3().setFromObject(mesh).getSize(size);const radius=Math.max(size.x,size.y,size.z)||1;camera.position.set(radius*1.45,radius*1.05,radius*1.65);camera.lookAt(0,0,0);scene.add(new THREE.HemisphereLight(0xffffff,0x657d78,2.7));const light=new THREE.DirectionalLight(0xffffff,3);light.position.set(radius,radius*2,radius);scene.add(light);const grid=new THREE.GridHelper(radius*4,24,0xd1dcde,0xe1e8e9);grid.position.y=-size.y/2-.05;scene.add(grid);return{renderer,scene,camera,mesh,radius}}
function makeThumbnail(p){const {renderer,scene,camera,mesh}=sceneFor(p,500,360);renderer.render(scene,camera);const src=renderer.domElement.toDataURL('image/png');renderer.dispose();mesh.material.dispose();return src}
let viewerControl=()=>{};
function viewerAction(a){viewerControl(a)}
function initViewer(p){const el=document.querySelector('#viewer');if(!geometries[p.id]){document.querySelector('#viewer-size').textContent='Preview unavailable';return}try{const v=sceneFor(p,el.clientWidth,el.clientHeight),{renderer,scene,camera,mesh,radius}=v;el.prepend(renderer.domElement);const controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;controls.minDistance=radius*.5;controls.maxDistance=radius*7;const initial=camera.position.clone();const box=new THREE.BoxHelper(mesh,0x158f83);box.visible=false;scene.add(box);const dims=geometries[p.id].userData.dimensions;const label=dims.map(n=>n.toLocaleString('en-GB',{maximumFractionDigits:1})).join(' × ')+' mm';document.querySelector('#viewer-size').textContent=label;document.querySelector('#dimensions').textContent='Bounding box · '+label+' · STL units assumed to be mm';viewerControl=a=>{if(a==='reset-view'){camera.position.copy(initial);controls.target.set(0,0,0)}else if(a==='bounds'){box.visible=!box.visible;document.querySelector('#dimensions').hidden=!box.visible}else camera.position.multiplyScalar(a==='zoom-in'?.82:1.22);controls.update()};let frame;const animate=()=>{frame=requestAnimationFrame(animate);controls.update();renderer.render(scene,camera)};animate();const observer=new ResizeObserver(()=>{camera.aspect=el.clientWidth/el.clientHeight;camera.updateProjectionMatrix();renderer.setSize(el.clientWidth,el.clientHeight)});observer.observe(el);disposeViewer=()=>{cancelAnimationFrame(frame);observer.disconnect();controls.dispose();renderer.dispose();mesh.material.dispose();box.geometry.dispose();box.material.dispose();viewerControl=()=>{}}}catch(e){document.querySelector('#viewer-size').textContent='WebGL unavailable';toast('3D preview unavailable in this browser.')}}
async function boot(){render();for(const p of parts){try{geometries[p.id]=prepareGeometry(await new STLLoader().loadAsync(({'makita.stl':makitaUrl,'keychain.stl':keychainUrl})[p.file]));thumbs[p.id]=makeThumbnail(p)}catch(e){console.error('STL preview',e)}}render()}
modal.addEventListener('close',()=>{modal.onpaste=null});
boot();
